/* For a row-major tensor of shape [d0 d1 d2], return the coordinate of flat index f along `axis` (0, 1 or 2).
   d0 itself isn't needed. */
int coord(int f, int d1, int d2, int axis) {
  return f;
}

answer.code:
int coord(int f, int d1, int d2, int axis) {
  if (axis == 0) return f / (d1 * d2);
  if (axis == 1) return f / d2 % d1;
  return f % d2;
}
